"""Apply accepted V228 overlay after legacy projection generators; preserve raw Master snapshots."""
import csv,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];A=ROOT/'app/src/main/assets';p=json.loads((ROOT/'master/changes/V228_MARTIAL_SEVEN_SOURCE.json').read_text());assert p['status']=='ACCEPTED'
def apply(rows,key):
 for r in rows:r.update(p['updates'][key].get(r['id'],{}))
 new=p['added'][key]
 if not any(r['id']==new['id'] for r in rows):rows.append(new.copy())
 assert len({r['id'] for r in rows})==len(rows)==222
 return rows
def save(path,d):path.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
cat=apply(json.loads((A/'skills/catalog.json').read_text()),'catalog');save(A/'skills/catalog.json',cat)
abilities=apply(json.loads((A/'skills/abilities.json').read_text()),'abilities');save(A/'skills/abilities.json',abilities)
with (ROOT/'docs/SKILL_ABILITY_FORMULAS.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(abilities[0]),lineterminator='\n');w.writeheader();w.writerows(abilities)
f=ROOT/'docs/SKILL_ACTION_DECISIONS.csv'
with f.open() as src:reader=csv.DictReader(src);fields=reader.fieldnames;rules=apply(list(reader),'rules')
with f.open('w',newline='') as out:w=csv.DictWriter(out,fieldnames=fields,lineterminator='\n');w.writeheader();w.writerows(rules)
d=json.loads((A/'skill-presentation/catalog.json').read_text());d['skills']=apply(d['skills'],'presentation');save(A/'skill-presentation/catalog.json',d)
with (ROOT/'docs/SKILL_PRESENTATION_MAPPING.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(d['skills'][0]),lineterminator='\n');w.writeheader();w.writerows(d['skills'])
learn=json.loads((A/'skills/mobile_learning.json').read_text());learn[p['added']['catalog']['id']]=p['learning'];save(A/'skills/mobile_learning.json',learn)
keys=['id','name','job','circle','kind','formula','coefficient','status','mpCost','cooldown','duration','allMp','evidence','description','cooldownEvidence','cooldownSource']
lines=['package com.projectdark.mobile;','/** Generated by base policy plus accepted V228 overlay. */','final class SkillAbilityData {',' static final String[][] ROWS={']
for r in abilities:lines.append('  {'+','.join(json.dumps(str(r[k]).lower() if isinstance(r[k],bool) else str(r[k]),ensure_ascii=False) for k in keys)+'},')
lines+=[' };','}'];(ROOT/'app/src/main/java/com/projectdark/mobile/SkillAbilityData.java').write_text('\n'.join(lines)+'\n')
keys=['id','name','mode','pattern','reach','minReach','mechanic','hits','contact','spatialEvidence','note','kind'];lines=['package com.projectdark.mobile;','','/** Generated from the reviewed per-ID decisions; do not infer rules from skill names. */','final class SkillActionData {','  static final String[][] ROWS={']
for r in rules:lines.append('    {'+', '.join(json.dumps(str(r[k]),ensure_ascii=False) for k in keys)+'},')
lines+=[' };','}'];(ROOT/'app/src/main/java/com/projectdark/mobile/SkillActionData.java').write_text('\n'.join(lines)+'\n')
print('Accepted V228 applied:222 stable IDs,7 labelled skills; raw source unchanged')
